-- ==============================================================================
-- TRANKILANDIA GYM · SEED DE DATOS REALES EXTRAÍDOS DE GYM.XLSM (390+ SOCIOS)
-- ==============================================================================

-- 1. Tabla de Socios del Gimnasio
create table if not exists public.socios (
  id text primary key,
  nombre text not null,
  dni text unique not null,
  email text,
  celular text,
  plan text not null,
  precio_plan numeric(10,2) not null,
  tipo_pago text not null check (tipo_pago in ('full', 'advance')),
  adelanto_pagado numeric(10,2) not null default 0,
  saldo_pendiente numeric(10,2) not null default 0,
  fecha_limite_pago text,
  metodo_pago text,
  numero_boleta text,
  estado_membresia text not null default 'activo',
  observaciones text,
  coach_asignado text,
  edad int,
  sexo text,
  created_at timestamp with time zone default timezone('utc'::text, now()) not null
);

-- Habilitar RLS
alter table public.socios enable row level security;
create policy "Socios visibles para usuarios autenticados" on public.socios for select to authenticated using (true);
create policy "Admins y Caja pueden gestionar socios" on public.socios for all to authenticated using (true);

-- 2. Insertar registros
on conflict (dni) do update set saldo_pendiente = excluded.saldo_pendiente, adelanto_pagado = excluded.adelanto_pagado;
